 CharacterMotor motor;motor.Reset({0,.94f,0},{1,0,0,0});UniformGravity gravity({0,-9.81f,0});double maxHeight=0;unsigned supported=0;start=std::chrono::steady_clock::now();
 for(int step=0;step<180;++step){const auto absolute=origin+V(motor.position);check(tiles.Collision(absolute,origin),"moving collision interest remains ready");motor.velocity={3,motor.velocity.y,0};physics.Step(1.f/60);motor.Step(physics,gravity,1.f/60);maxHeight=std::max(maxHeight,std::abs(double(motor.position.y)-.92));supported+=motor.result.supported;}
